/* @component: search-f */
(function () {
  function initSearchInputs() {
    document.querySelectorAll('.search-slot .js-container-input').forEach(function (fs) {
      if (fs.dataset.initialized === 'true') return;
      fs.dataset.initialized = 'true';
      const label = fs.querySelector('label');
      const legendSpan = fs.querySelector('legend span');
      if (label && legendSpan) {
        legendSpan.textContent = label.textContent;
      }
    });
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initSearchInputs);
  } else {
    initSearchInputs();
  }
  setTimeout(initSearchInputs, 300);
})();
/* @end: search-f */
